from pathlib import Path
import json,hashlib,datetime,sys
P=Path('docs/comics');SOURCE='https://chatgpt.com/share/6aea190f-d430-83ee-ab44-f243de7f2aec'
REFS=[dict(title='地方制度法第5條',url='https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0040003&flno=5'),dict(title='地方制度法第58條',url='https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0040003&flno=58'),dict(title='地方制度法第59條',url='https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0040003&flno=59'),dict(title='地方制度法第83-2條',url='https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0040003&flno=83-2'),dict(title='內政部我國地方制度概況',url='https://www.moi.gov.tw/cp.aspx?n=674')]
def node(label,detail='',tone='blue'):return dict(label=label,detail=detail,tone=tone)
def flow(title,items,arrow,note=''):return dict(kind='flow',title=title,items=items,arrow=arrow,note=note)
def paths(title,items,target,arrow,note=''):return dict(kind='paths',title=title,items=items,target=target,arrow=arrow,note=note)
def panel(heading,text,diagram,alt):return dict(heading=heading,text=text,diagram=diagram,alt=alt)
def spec(q,title,panels,answer,points,words,rationale,original):
 art=P/'art'/f'{q}.svg'
 art.write_text('<svg xmlns="http://www.w3.org/2000/svg" width="2160" height="720" viewBox="0 0 2160 720"><rect width="2160" height="720" fill="#f5faf8"/>'+''.join(f'<g transform="translate({720*i} 0)"><rect x="100" y="80" width="520" height="200" rx="16" fill="#e8f0fa" stroke="#446f9f" stroke-width="5"/><path d="M360 305v90m-25-30 25 30 25-30" fill="none" stroke="#a16d1d" stroke-width="9"/><rect x="100" y="420" width="520" height="210" rx="16" fill="#e0f3eb" stroke="#278574" stroke-width="5"/></g>' for i in range(3))+'</svg>')
 x=dict(id=q,subject='Civics',title=title,art=str(art),layoutVersion='native-fluid-v6',panels=panels,fourth=dict(answer=answer,points=points),protectedWords=words,sourceUrl=SOURCE,originalMaterialsChecked=True,originalChecked=dict(path=original,visualChecked=True),sourceGeneratedArtUsed=False,generationMethod='new selectable native HTML relationship diagrams with explicit Chinese roles/levels/actions; deterministic SVG fallback; imagegenCalls=0',rationale=rationale,designFile=f'docs/comics/{q}-design.txt',officialReferences=REFS,legalCheckedAt='2026-11-04',artSHA256=hashlib.sha256(art.read_bytes()).hexdigest(),visualChecked=False)
 (P/f'{q}-design.txt').write_text('精確HTML圖解；不使用來源AI或人物替代。\n'+rationale+'\n原卷：'+original+'\n'+json.dumps(panels,ensure_ascii=False,indent=2)+'\n')
 (P/f'{q}.json').write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def build(q):
 if q in ['q-932','q-933','q-934','q-935']:
  city='竹北市' if q in ['q-932','q-933'] else '花蓮市';county='新竹縣' if city=='竹北市' else '花蓮縣';admin=q in ['q-932','q-934'];role='行政機關' if admin else '立法機關';answer='C' if admin else 'D';agency='公所' if admin else '民代表會';opposite='立法' if admin else '行政'
  p1=panel('① 先辨層級：這裡是縣轄市',f'{city}隸屬{county}，是縣轄市，與鄉、鎮同層級。名字有「市」，不代表都是同一種層級。',dict(kind='nested',title='行政層級：縣之下',items=[node(county,tone='blue'),node(city+'（縣轄市）',tone='green')],note='縣轄市與鄉、鎮同層級。'),f'外層{county}、內層{city}，中文直接標明縣轄市。')
  p2=panel(f'② 再看欄位：本空問{role}',f'原表本空在{role}欄。縣轄市的{role}為{agency}，填入後是{city}{agency}，選{answer}。',paths('原表欄位→機關名稱',[node('本空：'+role,'先讀欄名，不只讀地名。','gold')],city+agency+'（'+answer+'）','依縣轄市制度填寫'),f'本空{role}經中文箭頭對應{city}{agency}，代號{answer}。')
  p3=panel('③ 對照同層級的兩種機關',f'同一個縣轄市，行政是公所，立法是民代表會。不要填成{opposite}機關，也不要套用政府／議會。',flow('同一層級，欄位不同',[node('行政機關：公所 C',tone='green'),node('立法機關：民代表會 D',tone='purple')],'換欄時，名稱也要換','政府／議會不是本題縣轄市的答案。'),f'精確中文對照行政公所C、立法民代表會D，不用顏色猜角色。')
  spec(q,f'{city}：先看層級，再看欄位',[p1,p2,p3],f'答案 {answer}：{agency}',[f'{city}是{county}的縣轄市。',f'本空問{role}，填{agency}。','不是看到「市」就一律填政府或議會。'],[city,county,'縣轄市','行政機關','立法機關','民代表會','公所','政府','議會','同層級'],f'原題是共同表格填機關；以中文標明{county}包含{city}的層級，再以{role}箭頭選{agency}，比人物情境更精確；四子各保留一份，不混合答案。','site/dist/assets/originals/src-more-055-original-mi111-62182cac1c84.png')
 elif q=='q-937':
  spec(q,'臺北市一般區：別漏里長',[panel('① 戶籍逐層看：直轄市、一般區、里','婷婷在臺北市大安區學府里。臺北市是直轄市，大安區是一般區；先確認制度，再判斷能選的地方公職。',flow('婷婷的戶籍層級',[node('臺北市：直轄市'),node('大安區：一般行政區',tone='gold'),node('學府里',tone='green')],'由上往下看戶籍層級'),'中文逐層標示臺北市、大安區、學府里。'),panel('② 直轄市層級：選A、B','直轄市層級可選市長A、市議員B。不能再重複加入縣市長E、縣市議員F；它們是不同類別。',paths('直轄市層級的公職',[node('A：直轄市市長',tone='blue'),node('B：直轄市議員',tone='green')],'直轄市層級：2類','依本題表的代號列出'),'A市長及B市議員兩項以中文明示，合計2類。'),panel('③ 一般區長不選，里長仍要選','大安區長由市長依法任用，不是本題另選的公職；學府里的里長I仍由里民選出，不能一起漏掉。',flow('一般區與里長分開判斷',[node('大安區長：依法任用','一般區長不是民選。','gold'),node('學府里長 I：里民選出','補上本題漏選的里長。','green')],'區長不是民選，不影響里長民選'),'中文對照一般區長任用及里長I民選。')],'答案 A、B、I：共3類地方公職',['A市長＋B市議員＋I里長。','大安區是一般區，不加區長或區民代表。','本題算公職類別，不把公投另加進來。'],['婷婷','臺北市','大安區','學府里','直轄市','一般行政區','依法任用','里民選出','地方公職','里長','市議員'],'本題核心為戶籍制度與公職代號，精確HTML逐層標明角色與2＋1類，不用無字人物或選票圖示讓讀者猜，依原表保留ABI。','site/dist/assets/originals/src-more-055-original-mi154-9ac8a53a50c4.png')
 elif q=='q-938':
  spec(q,'和平區：自治區公職與里長都要列',[panel('① 和平區是山地原住民區','阿承在臺中市和平區平等里。和平區具有自治地位，與一般行政區的區長任用制度不同。',flow('阿承的戶籍層級',[node('臺中市：直轄市'),node('和平區：山地原住民區',tone='gold'),node('平等里',tone='green')],'由上往下判斷制度'),'臺中市、和平區、平等里層級及山地原住民區明標。'),panel('② 市與自治區：A、B、C、D','先有臺中市長A、市議員B；和平區還能選區長C、區民代表D。依戶籍制度判斷，不是只看個人有無原住民身分。',paths('市與自治區的公職',[node('市層級：A市長、B市議員',tone='blue'),node('自治區：C區長、D區民代表',tone='purple')],'先列出4類地方公職','兩層制度分別適用'),'中文標示市A/B、自治區C/D，各2類合計4類。'),panel('③ 平等里長I也要選','別漏平等里的里長I，總共A、B、C、D、I五類。C已是本地區長，不能再把鄉鎮市長G重複加進來。',flow('最後補上里長',[node('A、B、C、D：4類',tone='blue'),node('加I：平等里長，合計5類',tone='green')],'把里長加入完整清單'),'以中文及數字4類加里長I成5類，不使用件數或未標圖示。')],'答案 A、B、C、D、I：共5類',['臺中市層級A、B。','和平自治區層級C、D。','平等里長I，不重複加G、H。'],['阿承','臺中市','和平區','平等里','山地原住民區','一般行政區','區民代表','地方公職','原住民身分','依法任用'],'精確HTML區分市/山地原住民自治區/里三層制度及5類代號，保留只看戶籍制度不只看個人身分的限制，不把C/G或D/H重複算。','site/dist/assets/originals/src-more-055-original-mi154-9ac8a53a50c4.png')
 elif q=='q-939':
  spec(q,'新竹市：辨清市的種類，別漏里長',[panel('① 新竹市與縣同層級','小裕在新竹市東區光明里。新竹市是與縣同層級的市，不是直轄市，也不是新竹縣下的縣轄市。',flow('小裕的戶籍層級',[node('新竹市：與縣同層級的市'),node('東區：一般行政區',tone='gold'),node('光明里',tone='green')],'由上往下判斷制度'),'中文明標新竹市與縣同層級、東區一般區、光明里。'),panel('② 市層級：對應E、F','新竹市長對應縣（市）長E，市議員對應縣（市）議員F。A、B是直轄市類別，不能因都有市字就選錯。',paths('新竹市的公職代號',[node('E：縣（市）長',detail='本題為新竹市長。',tone='blue'),node('F：縣（市）議員',detail='本題為新竹市議員。',tone='green')],'市層級：E、F，共2類','依原表的公職類別對應'),'E與F的原表類別及本題市長、市議員清楚對照。'),panel('③ 東區長不另選，里長仍民選','東區是一般區，區長依法任用；光明里仍可選里長I。因此E、F之外補I，不能把一般區長也算入民選。',flow('一般區與里分開看',[node('東區長：依法任用','不是另外民選的區長。','gold'),node('光明里長 I：里民選出','與E、F合計3類。','green')],'一般區長非民選，不等於里長非民選'),'依法任用的東區長與里民選出的里長I，中文直接標明。')],'答案 E、F、I：共3類地方公職',['新竹市不是直轄市，也不是縣轄市。','E市長＋F市議員＋I里長。','一般區長依法任用，里長仍由里民選出。'],['小裕','新竹市','新竹縣','東區','光明里','縣轄市','直轄市','一般行政區','縣（市）長','縣（市）議員','依法任用','里民選出'],'精確HTML分辨新竹市/竹北市/直轄市不同制度，E/F類別與一般區/里長分別對應，不用模糊市名或無字票券替代。','site/dist/assets/originals/src-more-055-original-mi154-9ac8a53a50c4.png')
 else:raise ValueError(q)
if __name__=='__main__':build(sys.argv[1])
